import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CdGZLcRD.js";var i=JSON.parse(`{"title":"Relationship Specification","description":"","frontmatter":{},"headers":[],"relativePath":"guides/the-manual/relational-data/spec.md","filePath":"guides/the-manual/relational-data/spec.md"}`),a={name:`guides/the-manual/relational-data/spec.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="relationship-specification" tabindex="-1">Relationship Specification <a class="header-anchor" href="#relationship-specification" aria-label="Permalink to “Relationship Specification”">​</a></h1><p>This page is the normative reference for how WarpDrive relationships behave: what a relationship payload may contain, what each field kind requires of the API, and how those requirements are enforced. The words <strong>MUST</strong>, <strong>MUST NOT</strong>, <strong>SHOULD</strong> and <strong>MAY</strong> are used as in <a href="https://www.rfc-editor.org/rfc/rfc2119" target="_blank" rel="noreferrer">RFC 2119</a>.</p><p>The rest of the <a href="./">Relational Data guide</a> explains these rules with examples; this page only states them.</p><h2 id="_1-terms" tabindex="-1">1. Terms <a class="header-anchor" href="#_1-terms" aria-label="Permalink to “1. Terms”">​</a></h2><ul><li><strong>Relationship payload</strong> — the value of a key inside a resource&#39;s <code>relationships</code> member: <code>{ data?, links?, meta? }</code>.</li><li><strong>Linkage</strong> — a <code>{ type, id }</code> resource identifier inside <code>data</code>.</li><li><strong>Included</strong> — a linkage is <em>included</em> in a document when a resource object with the same <code>type</code> and <code>id</code> appears in that document&#39;s <code>data</code> or <code>included</code> members.</li><li><strong>Strict kinds</strong> — the <code>resource</code> and <code>collection</code> field kinds.</li><li><strong>Legacy kinds</strong> — the <code>belongsTo</code> and <code>hasMany</code> field kinds.</li><li><strong>Remote state</strong> — the membership, <code>links</code> and <code>meta</code> last received from the API.</li><li><strong>Local state</strong> — the membership including unsaved mutations.</li></ul><h2 id="_2-payload-shape" tabindex="-1">2. Payload Shape <a class="header-anchor" href="#_2-payload-shape" aria-label="Permalink to “2. Payload Shape”">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>2.1</td><td>A relationship payload MUST be an object. It MAY contain any of <code>data</code>, <code>links</code> and <code>meta</code>.</td></tr><tr><td>2.2</td><td>For a <code>resource</code> or <code>belongsTo</code> field, <code>data</code> MUST be a single linkage or <code>null</code>.</td></tr><tr><td>2.3</td><td>For a <code>collection</code> or <code>hasMany</code> field, <code>data</code> MUST be an array of linkages (possibly empty).</td></tr><tr><td>2.4</td><td><code>data: null</code> (resource) and <code>data: []</code> (collection) mean the relationship is <strong>known to be empty</strong>. An absent <code>data</code> member means the membership is <strong>unknown</strong>; it never means empty.</td></tr><tr><td>2.5</td><td>Each of <code>data</code>, <code>links</code> and <code>meta</code>, when present, replaces the previous value of that member in the cache. An absent member leaves the cached value untouched.</td></tr><tr><td>2.6</td><td>Pagination links (<code>first</code>, <code>last</code>, <code>prev</code>, <code>next</code>) MAY appear in <code>links</code> and are exposed on the document, but relationship membership is never paginated: <code>data</code> is always the complete membership.</td></tr></tbody></table><h2 id="_3-rules-for-resource-and-collection-relationships" tabindex="-1">3. Rules For <code>resource</code> And <code>collection</code> Relationships <a class="header-anchor" href="#_3-rules-for-resource-and-collection-relationships" aria-label="Permalink to “3. Rules For resource And collection Relationships”">​</a></h2><p>These rules apply to the strict kinds only. They are what make the kinds safe to materialize eagerly and without autofetch.</p><h3 id="_3-1-full-inclusion" tabindex="-1">3.1 Full inclusion <a class="header-anchor" href="#_3-1-full-inclusion" aria-label="Permalink to “3.1 Full inclusion”">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>3.1.1</td><td>Every linkage in a strict relationship&#39;s <code>data</code> MUST be included in the same document.</td></tr><tr><td>3.1.2</td><td>Materializing a strict relationship whose <code>data</code> references a resource with no data in the cache is an error.</td></tr></tbody></table><h3 id="_3-2-async-true" tabindex="-1">3.2 <code>async: true</code> <a class="header-anchor" href="#_3-2-async-true" aria-label="Permalink to “3.2 async: true”">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>3.2.1</td><td>Every payload for the relationship MUST provide a <code>links</code> object containing a <code>related</code> link.</td></tr><tr><td>3.2.2</td><td><code>data</code> MAY be omitted. When present, rule 3.1 applies.</td></tr><tr><td>3.2.3</td><td>The related data is never fetched automatically. <code>doc.fetch()</code> requests the <code>related</code> link (or <code>self</code> when there is no <code>related</code> link), caches the response as a request document keyed by <code>doc.identifier</code>, writes the response&#39;s <code>data</code> into the relationship&#39;s remote state, and resolves with the relationship document itself.</td></tr></tbody></table><h3 id="_3-3-async-false-the-default" tabindex="-1">3.3 <code>async: false</code> (the default) <a class="header-anchor" href="#_3-3-async-false-the-default" aria-label="Permalink to “3.3 async: false (the default)”">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>3.3.1</td><td>Whenever the relationship is present in a payload, its <code>data</code> member MUST be present. Links-only and meta-only payloads are invalid.</td></tr><tr><td>3.3.2</td><td>Rule 3.1 applies: every linkage MUST be included.</td></tr><tr><td>3.3.3</td><td>The relationship SHOULD NOT provide <code>links</code>. Sync relationships are fully included, so links are never needed to load them.</td></tr></tbody></table><h3 id="_3-4-enforcement" tabindex="-1">3.4 Enforcement <a class="header-anchor" href="#_3-4-enforcement" aria-label="Permalink to “3.4 Enforcement”">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>JSON:API validator</th><th>Graph</th><th>Runtime</th></tr></thead><tbody><tr><td>3.1.1</td><td>error</td><td>—</td><td>—</td></tr><tr><td>3.1.2</td><td>—</td><td>—</td><td>throws on access to <code>data</code></td></tr><tr><td>3.2.1</td><td>error</td><td>assertion (dev builds) on every payload</td><td>—</td></tr><tr><td>3.3.1</td><td>error</td><td>—</td><td>—</td></tr><tr><td>3.3.3</td><td>warning by default; error when <code>strict.syncRelationshipLinks</code> is <code>true</code></td><td>—</td><td>—</td></tr><tr><td>2.2, 2.3</td><td>error</td><td>assertion (dev builds)</td><td>—</td></tr></tbody></table><p>The validator runs in development builds when the <code>JSON_API_CACHE_VALIDATION_ERRORS</code> feature is active (or <code>LOG_CACHE</code> is enabled) and reports on documents received through requests. Graph assertions run in development builds for every payload, including <code>store.push</code>. Runtime errors are thrown in every build.</p><h2 id="_4-rules-for-belongsto-and-hasmany-relationships" tabindex="-1">4. Rules For <code>belongsTo</code> And <code>hasMany</code> Relationships <a class="header-anchor" href="#_4-rules-for-belongsto-and-hasmany-relationships" aria-label="Permalink to “4. Rules For belongsTo And hasMany Relationships”">​</a></h2><p>The legacy kinds exist for apps migrating from <code>@warp-drive/legacy/model</code> and keep that library&#39;s behavior:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>4.1</td><td><code>options.async</code> and <code>options.inverse</code> MUST be declared explicitly.</td></tr><tr><td>4.2</td><td><code>async: true</code> relationships are wrapped in promise proxies and fetch on access through the configured adapter, or through the <code>related</code> link in <a href="./../misc/links-mode">LinksMode</a>.</td></tr><tr><td>4.3</td><td><code>async: false</code> relationships MAY reference resources that are not included; WarpDrive materializes an empty record for them. In LinksMode the stricter LinksMode rules apply instead.</td></tr><tr><td>4.4</td><td>Payloads MAY carry <code>links</code> regardless of <code>async</code>.</td></tr><tr><td>4.5</td><td>A remote update resets local changes unless <code>options.resetOnRemoteUpdate</code> is <code>false</code> or the field is in LinksMode.</td></tr></tbody></table><p>Rules 2.x apply to the legacy kinds as well.</p><h2 id="_5-values-and-mutation" tabindex="-1">5. Values And Mutation <a class="header-anchor" href="#_5-values-and-mutation" aria-label="Permalink to “5. Values And Mutation”">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>5.1</td><td>The value of a strict relationship field is a <code>ReactiveRelationshipDocument</code> exposing <code>data</code>, <code>links</code>, <code>meta</code>, <code>identifier</code> and <code>fetch()</code>. <code>identifier</code> is the request key for the relationship&#39;s <code>related</code> (or <code>self</code>) link, or <code>null</code> when it has neither. Assigning the field itself is an error.</td></tr><tr><td>5.2</td><td><code>data</code> MAY be assigned (resource: a record or <code>null</code>; collection: an array of records) and, for collections, mutated with the array mutation methods, only when the owning record is editable: any LegacyMode record, or a PolarisMode record returned by <code>checkout()</code>. On an immutable record every mutation is an error.</td></tr><tr><td>5.3</td><td>A record MUST appear at most once in a collection; adding a duplicate is an error.</td></tr><tr><td>5.4</td><td><code>links</code> and <code>meta</code> are server-owned: they always reflect remote state and MUST NOT be affected by local mutation.</td></tr><tr><td>5.5</td><td>Whether a relationship has local changes not yet confirmed by the API is reported by the cache (<code>changedRelationships</code>), not by the document.</td></tr><tr><td>5.6</td><td>Immutable PolarisMode records render remote state; editable records render local state. Inverses follow the same rule.</td></tr><tr><td>5.7</td><td>Local state becomes remote state when a payload confirming it is received (typically the save response). A save response that omits the relationship leaves its local state unconfirmed. <code>commit()</code> promotes the local state of every changed relationship to remote state.</td></tr><tr><td>5.8</td><td>When serializing a relationship for a request, only the identifiers of <code>data</code> are sent. <code>links</code> and <code>meta</code> MUST NOT be echoed back to the API.</td></tr></tbody></table><h2 id="_6-size-guard" tabindex="-1">6. Size Guard <a class="header-anchor" href="#_6-size-guard" aria-label="Permalink to “6. Size Guard”">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Statement</th></tr></thead><tbody><tr><td>6.1</td><td>When <code>Store.maxCollectionRelationshipSize</code> is a number, any remote payload for a <code>collection</code> field whose <code>data</code> array is longer than that number causes an error to be thrown asynchronously after the payload has been applied.</td></tr><tr><td>6.2</td><td>The guard counts members in a single payload. It does not apply to legacy <code>hasMany</code> fields, to <code>resource</code> fields, or to local mutations.</td></tr><tr><td>6.3</td><td>Lists that need pagination, sorting or filtering SHOULD be loaded with <a href="./advanced/pagination">top-level requests</a> rather than through a relationship.</td></tr></tbody></table>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};